import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors", () => {
  test("the same vendor name is allowed in a different tenant", { tag: "@VEN-04" }, async ({ apiAs }) => {
    // Arrange: a vendor with the same name already exists in another tenant (Globex Procurement).
    // The name is unique per run because tests share one database; the cross-tenant overlap is what is under test.
    const sharedName = uniqueName("Acme Freight");
    const globex = await apiAs("otherTenant");
    const seeded = await globex.post("/api/vendors", {
      data: {
        name: sharedName,
        category: "logistics",
        contact_email: "ops@globex-freight.example",
      },
    });
    expect(seeded.status(), "seed vendor in Globex Procurement").toBe(201);

    // Act: the Northwind member creates a vendor with the same name.
    const northwind = await apiAs("member");
    const response = await northwind.post("/api/vendors", {
      data: {
        name: sharedName,
        category: "logistics",
        contact_email: "ops@acmefreight.example",
      },
    });

    // Assert
    expect(response.status()).toBe(201);
    const created = await response.json();
    expect(created.name).toBe(sharedName);
    expect(created.id).not.toBe((await seeded.json()).id);
  });
});
